Here's how to create a **custom theme hook**:

```tsx
import { useColorScheme } from 'nativewind';

export const useThemeColors = () => {
  const { isDarkColorScheme } = useColorScheme();

  return {
    primary: isDarkColorScheme ? '#ffffff' : '#000000',
    secondary: isDarkColorScheme ? '#333333' : '#f0f0f0',
  };
};
```

**Key benefits:**
- ✅ Reusable across components
- ✅ Automatic theme switching
- ✅ Type-safe color definitions

Absolutely! Here's a practical example:

```tsx
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { useThemeColors } from '~/lib/useThemeColors';

const MyComponent = () => {
  const colors = useThemeColors();

  return (
    <View>
      <MaterialCommunityIcons 
        name="heart" 
        color={colors.primary} 
        size={24} 
      />
      <Text style={{ color: colors.secondary }}>
        Themed text!
      </Text>
    </View>
  );
};
```

> **Pro tip:** This automatically adapts to light/dark mode changes!

Great question! Here's the **type-safe version**:

```tsx
type ThemeColors = {
  primary: string;
  secondary: string;
  accent: string;
  background: string;
};

export const useThemeColors = (): ThemeColors => {
  const { isDarkColorScheme } = useColorScheme();

  return {
    primary: isDarkColorScheme 
      ? 'hsl(0 0% 98%)' 
      : 'hsl(240 10% 3.9%)',
    secondary: isDarkColorScheme 
      ? 'hsl(240 3.7% 15.9%)' 
      : 'hsl(240 4.8% 95.9%)',
    accent: isDarkColorScheme 
      ? 'hsl(0 0% 98%)' 
      : 'hsl(240 5.9% 10%)',
    background: isDarkColorScheme 
      ? 'hsl(240 10% 3.9%)' 
      : 'hsl(0 0% 100%)',
  } as const;
};
```

**Benefits:**
- 🎯 Full IntelliSense support
- 🛡️ Compile-time error checking
- 📚 Self-documenting code
